const ORANGE = "#E65100";
const RED    = "#B71C1C";

export default function KYCAgentic() {
  const [sel, setSel]       = useState(null);
  const [hov, setHov]       = useState(null);

  const step = STEPS.find(s => s.id === sel);

  return (
    <div style={{ fontFamily:"'Inter','Segoe UI',sans-serif", background:"#F5F7FF", minHeight:"100vh" }}>

      {/* ── HEADER ── */}
      <div style={{ background:"#1A3A8F", padding:"14px 28px", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
        <div>
          <div style={{ fontSize:11, color:"#93C5FD", fontWeight:700, letterSpacing:"0.12em", textTransform:"uppercase", marginBottom:3 }}>
            BCG · Agentic AI-Enabled KYC
          </div>
          <div style={{ fontSize:20, fontWeight:800, color:"#FFFFFF", letterSpacing:"-0.01em" }}>
            Interactive KYC Workflow — Click Any Step to Expand
          </div>
        </div>
        {sel && (
          <button onClick={() => setSel(null)} style={{ background:"rgba(255,255,255,0.15)", border:"1px solid rgba(255,255,255,0.3)", color:"#fff", borderRadius:6, padding:"7px 16px", cursor:"pointer", fontSize:13, fontWeight:600 }}>
            ✕ Close Detail
          </button>
        )}
      </div>

      {/* ── INSTRUCTION BAR ── */}
      <div style={{ background:"#EFF6FF", borderBottom:"1px solid #BFDBFE", padding:"8px 28px", fontSize:12, color:"#1565C0", fontWeight:500, display:"flex", alignItems:"center", gap:8 }}>
        <span style={{ fontSize:16 }}>👆</span>
        Click any of the 10 numbered steps on the workflow image below to see the full detail — what happens, documents required, human oversight, pass conditions and failure paths.
        {sel && <span style={{ marginLeft:"auto", fontWeight:700, color:"#1A3A8F" }}>Now viewing: Step {sel} — {step?.title}</span>}
      </div>

      {/* ── WORKFLOW IMAGE WITH OVERLAYS ── */}
      <div style={{ position:"relative", width:"100%", lineHeight:0, boxShadow:"0 2px 12px rgba(0,0,0,0.12)" }}>
        <img
          src={IMG}
          alt="Agentic AI-Enabled KYC Workflow — BCG"
          style={{ width:"100%", display:"block" }}
          draggable={false}
        />

        {/* Overlay tiles */}
        {TILES.map(t => {
          const isHov = hov === t.id;
          const isSel = sel === t.id;
          return (
            <div
              key={t.id}
              onMouseEnter={() => setHov(t.id)}
              onMouseLeave={() => setHov(null)}
              onClick={() => setSel(isSel ? null : t.id)}
              style={{
                position:"absolute",
                left:t.left, top:t.top, width:t.width, height:t.height,
                cursor:"pointer",
                background: isSel
                  ? "rgba(26,58,143,0.13)"
                  : isHov
                    ? "rgba(26,58,143,0.07)"
                    : SHOW_CLICK_AREAS
                      ? "rgba(255,193,7,0.16)"
                      : "transparent",
                border: isSel
                  ? "2.5px solid #1A3A8F"
                  : isHov
                    ? "2px dashed rgba(27,94,32,0.65)"
                    : SHOW_CLICK_AREAS
                      ? "2px solid rgba(255,152,0,0.85)"
                      : "2px solid transparent",
                borderRadius:10,
                transition:"background 0.15s, border-color 0.15s, box-shadow 0.15s",
                boxSizing:"border-box",
                overflow:"hidden",
                zIndex:2,
                boxShadow: isSel
                  ? "0 0 0 2px rgba(255,255,255,0.75) inset"
                  : "none",
              }}
            >
              {/* Top-right expand chip */}
              <div style={{
                position:"absolute", top:6, right:6,
                background: isSel ? "#1A3A8F" : isHov ? "#1565C0" : "rgba(26,58,143,0.55)",
                color:"#fff",
                fontSize:9, fontWeight:800, letterSpacing:"0.08em",
                padding:"3px 7px", borderRadius:4,
                transition:"all 0.15s",
                display: (isSel || isHov || SHOW_CLICK_AREAS) ? "flex" : "none",
                alignItems:"center", gap:4,
                lineHeight:1.2,
              }}>
                {isSel ? "▲ OPEN" : "▼ EXPAND"}
              </div>
              {/* Step number badge bottom-left */}
              {isSel && (
                <div style={{
                  position:"absolute", bottom:6, left:6,
                  background:"#1A3A8F", color:"#fff",
                  fontSize:9, fontWeight:800, padding:"2px 8px", borderRadius:3,
                }}>
                  STEP {t.id} SELECTED
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* ── DETAIL PANEL ── */}
      {step && (
        <div style={{ background:"#FFFFFF", borderTop:"3px solid #1A3A8F", padding:"32px 36px 48px" }}>

          {/* Detail header */}
          <div style={{ display:"flex", alignItems:"flex-start", gap:18, marginBottom:28, paddingBottom:20, borderBottom:"2px solid #DBEAFE" }}>
            <div style={{ minWidth:56, height:56, borderRadius:"50%", background:GREEN, display:"flex", alignItems:"center", justifyContent:"center", color:"#fff", fontSize:22, fontWeight:900, flexShrink:0 }}>
              {step.id}
            </div>
            <div style={{ flex:1 }}>
              <div style={{ fontSize:11, fontWeight:800, letterSpacing:"0.14em", textTransform:"uppercase", color:"#3B82F6", marginBottom:4 }}>
                STEP {step.num}
              </div>
              <div style={{ fontSize:24, fontWeight:800, color:"#0D0D0D", letterSpacing:"-0.01em", marginBottom:6 }}>
                {step.title}
              </div>
              <span style={{ display:"inline-flex", alignItems:"center", gap:6, background:step.agentColor + "18", border:"1px solid " + step.agentColor + "44", color:step.agentColor, fontSize:11, fontWeight:700, padding:"4px 12px", borderRadius:5 }}>
                🤖 {step.agent}
              </span>
            </div>
          </div>

          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:24 }}>

            {/* Left column */}
            <div>
              {/* What happens */}
              <Section title="What Happens in This Step" icon="⚙️" color={GREEN}>
                {step.what.map((w,i) => <Para key={i}>{w}</Para>)}
              </Section>

              {/* Timeline */}
              <Section title="Timeline" icon="🕐" color="#1565C0">
                <Para>{step.timeline}</Para>
              </Section>

              {/* Human Required */}
              <Section title="Human Oversight Required" icon="👤" color={ORANGE}>
                <Para>{step.human}</Para>
              </Section>
            </div>

            {/* Right column */}
            <div>
              {/* Documents */}
              <Section title="Documents / Evidence Required" icon="📄" color="#6A1B9A">
                <ul style={{ margin:0, padding:"0 0 0 18px" }}>
                  {step.docs.map((d,i) => (
                    <li key={i} style={{ fontSize:13, color:"#1A1A1A", marginBottom:6, lineHeight:1.6 }}>{d}</li>
                  ))}
                </ul>
              </Section>

              {/* Pass */}
              <Section title="Step Passes When" icon="✅" color="#1565C0">
                <ul style={{ margin:0, padding:"0 0 0 18px" }}>
                  {step.passConditions.map((p,i) => (
                    <li key={i} style={{ fontSize:13, color:"#1A1A1A", marginBottom:6, lineHeight:1.6 }}>{p}</li>
                  ))}
                </ul>
                <div style={{ marginTop:10, background:"#EFF6FF", border:"1px solid #BFDBFE", borderRadius:6, padding:"8px 12px", fontSize:13, fontWeight:700, color:"#1A3A8F" }}>
                  → {step.passNext}
                </div>
              </Section>
            </div>
          </div>

          {/* Failure section — full width */}
          <div style={{ marginTop:24, display:"grid", gridTemplateColumns:"1fr 1fr", gap:20 }}>
            <Section title="Failure Cases" icon="❌" color={RED}>
              <ol style={{ margin:0, padding:"0 0 0 18px" }}>
                {step.failureCases.map((f,i) => (
                  <li key={i} style={{ fontSize:13, color:"#1A1A1A", marginBottom:7, lineHeight:1.6 }}>{f}</li>
                ))}
              </ol>
            </Section>
            <Section title="If Step Fails — Actions" icon="🔄" color="#E65100">
              <ul style={{ margin:0, padding:"0 0 0 18px" }}>
                {step.failedActions.map((a,i) => (
                  <li key={i} style={{ fontSize:13, color:"#1A1A1A", marginBottom:7, lineHeight:1.6 }}>{a}</li>
                ))}
              </ul>
            </Section>
          </div>

          {/* Close button */}
          <div style={{ textAlign:"center", marginTop:32 }}>
            <button
              onClick={() => setSel(null)}
              style={{ background:GREEN, color:"#fff", border:"none", borderRadius:8, padding:"11px 32px", cursor:"pointer", fontSize:14, fontWeight:700 }}
            >
              ✕ Close Step Detail
            </button>
          </div>
        </div>
      )}

      {/* ── STEP QUICK NAV ── */}
      <div style={{ background:"#1A3A8F", padding:"14px 28px", display:"flex", gap:8, flexWrap:"wrap", justifyContent:"center" }}>
        {STEPS.map(s => (
          <button
            key={s.id}
            onClick={() => setSel(sel === s.id ? null : s.id)}
            style={{
              background: sel===s.id ? "#FFFFFF" : "rgba(255,255,255,0.12)",
              color: sel===s.id ? "#1A3A8F" : "#EFF6FF",
              border:"1px solid rgba(255,255,255,0.25)",
              borderRadius:5, padding:"5px 12px", cursor:"pointer",
              fontSize:11, fontWeight:700, transition:"all 0.15s",
            }}
          >
            {s.id}. {s.title.length > 18 ? s.title.slice(0,18)+"…" : s.title}
          </button>
        ))}
      </div>

    </div>
  );
}

/* ─── HELPERS ─────────────────────────────────────────────── */
function Section({ title, icon, color, children }) {
  return (
    <div style={{ marginBottom:20 }}>
      <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:10, paddingBottom:6, borderBottom:"2px solid " + color + "33" }}>
        <span style={{ fontSize:16 }}>{icon}</span>
        <span style={{ fontSize:12, fontWeight:800, textTransform:"uppercase", letterSpacing:"0.1em", color:color }}>{title}</span>
      </div>
      {children}
    </div>
  );
}

function Para({ children }) {
  return <p style={{ fontSize:13, color:"#1A1A1A", lineHeight:1.7, margin:"0 0 8px" }}>{children}</p>;
}
